    12→// secretPattern matches high-entropy strings that may be secrets.
    13→var secretPattern = regexp.MustCompile(`[A-Za-z0-9/+_=-]{10,}`)
    14→
    15→const entropyThreshold = 4.5
    16→
    17→// String replaces high-entropy strings matching secretPattern with [REDACTED].
    18→func String(s string) string {
    19→	locs := secretPattern.FindAllStringIndex(s, -1)
    20→	if len(locs) == 0 {
    21→		return s
    22→	}
    23→	var b strings.Builder
    24→	prev := 0
    25→	for _, loc := range locs {
    26→		b.WriteString(s[prev:loc[0]])
    27→		match := s[loc[0]:loc[1]]
    28→		if isSecret(match) {
    29→			b.WriteString("[REDACTED]")
    30→		} else {
    31→			b.WriteString(match)
    32→		}
    33→		prev = loc[1]
    34→	}
    35→	b.WriteString(s[prev:])
    36→	return b.String()
    37→}
