    62→// JSONLContent parses each line as JSON to determine which string values
    63→// need redaction, then performs targeted replacements on the raw JSON bytes.
    64→// Lines with no secrets are returned unchanged, preserving original formatting.
    65→func JSONLContent(content string) (string, error) {
    66→	lines := strings.Split(content, "\n")
    67→	var b strings.Builder
    68→	for i, line := range lines {
    69→		if i > 0 {
    70→			b.WriteByte('\n')
    71→		}
    72→		trimmed := strings.TrimSpace(line)
    73→		if trimmed == "" {
    74→			b.WriteString(line)
    75→			continue
    76→		}
    77→		var parsed any
    78→		if err := json.Unmarshal([]byte(trimmed), &parsed); err != nil {
    79→			b.WriteString(line)
    80→			continue
    81→		}
    82→		repls := collectJSONLReplacements(parsed)
    83→		if len(repls) == 0 {
    84→			b.WriteString(line)
    85→			continue
    86→		}
    87→		result := line
    88→		for _, r := range repls {
    89→			origJSON, err := jsonEncodeString(r[0])
    90→			if err != nil {
    91→				return "", err
    92→			}
    93→			replJSON, err := jsonEncodeString(r[1])
    94→			if err != nil {
    95→				return "", err
    96→			}
    97→			result = strings.ReplaceAll(result, origJSON, replJSON)
    98→		}
    99→		b.WriteString(result)
   100→	}
   101→	return b.String(), nil
   102→}
