   104→// collectJSONLReplacements walks a parsed JSON value and collects unique
   105→// (original, redacted) string pairs for values that need redaction.
   106→func collectJSONLReplacements(v any) [][2]string {
   107→	seen := make(map[string]bool)
   108→	var repls [][2]string
   109→	var walk func(v any)
   110→	walk = func(v any) {
   111→		switch val := v.(type) {
   112→		case map[string]any:
   113→			if shouldSkipJSONLObject(val) {
   114→				return
   115→			}
   116→			for k, child := range val {
   117→				if shouldSkipJSONLField(k) {
   118→					continue
   119→				}
   120→				walk(child)
   121→			}
   122→		case []any:
   123→			for _, child := range val {
   124→				walk(child)
   125→			}
   126→		case string:
   127→			redacted := String(val)
   128→			if redacted != val && !seen[val] {
   129→				seen[val] = true
   130→				repls = append(repls, [2]string{val, redacted})
   131→			}
   132→		}
   133→	}
   134→	walk(v)
   135→	return repls
   136→}
