   138→// shouldSkipJSONLField returns true if a JSON key should be excluded from scanning/redaction.
   139→// Skips "signature" (exact) and any key ending in "id" (case-insensitive).
   140→func shouldSkipJSONLField(key string) bool {
   141→	if key == "signature" {
   142→		return true
   143→	}
   144→	lower := strings.ToLower(key)
   145→	return strings.HasSuffix(lower, "id") || strings.HasSuffix(lower, "ids")
   146→}
   147→
   148→// shouldSkipJSONLObject returns true if the object has "type":"image".
   149→func shouldSkipJSONLObject(obj map[string]any) bool {
   150→	t, ok := obj["type"].(string)
   151→	return ok && t == "image"
   152→}
