   154→// isSecret returns true if match is a high-entropy string that looks like a secret.
   155→func isSecret(match string) bool {
   156→	return shannonEntropy(match) > entropyThreshold
   157→}
   158→
   159→func shannonEntropy(s string) float64 {
   160→	if len(s) == 0 {
   161→		return 0
   162→	}
   163→	freq := make(map[byte]int)
   164→	for i := range len(s) {
   165→		freq[s[i]]++
   166→	}
   167→	length := float64(len(s))
   168→	var entropy float64
   169→	for _, count := range freq {
   170→		p := float64(count) / length
   171→		entropy -= p * math.Log2(p)
   172→	}
   173→	return entropy
   174→}
