   176→// jsonEncodeString returns the JSON encoding of s without HTML escaping.
   177→func jsonEncodeString(s string) (string, error) {
   178→	var buf bytes.Buffer
   179→	enc := json.NewEncoder(&buf)
   180→	enc.SetEscapeHTML(false)
   181→	if err := enc.Encode(s); err != nil {
   182→		return "", fmt.Errorf("json encode string: %w", err)
   183→	}
   184→	return strings.TrimSuffix(buf.String(), "\n"), nil
   185→}
